headlines.statement:
∀ {m n : ℕ} (r : Fin m → ℕ) (c : Fin n → ℕ) (htotal : ∑ i, r i = ∑ j, c j) (h : ℕ),
  have p := Math115.CompletionOuterSchedule.physicalSmallCount r c;
  have base := Math115.CompletionOuterSchedule.physicalMassBase r;
  have T :=
    Math115.CompletionOuterSchedule.walkCount p OAI.ContingencyTables.CompletionCounts.dimensionAllowance base h;
  have R := Math115.CompletionOuterSchedule.restartCount p h;
  have hStep :=
    Math115.CompletionOuterSchedule.stepPrecision p OAI.ContingencyTables.CompletionCounts.dimensionAllowance base h;
  have hTerminal := Math115.CompletionOuterSchedule.terminalPrecision p h;
  ↑(OAI.ContingencyTables.FirstSuccess.variation
        (OAI.ContingencyTables.FirstSuccess.mapLaw OAI.ContingencyTables.FirstSuccess.uniformLaw
          (Math115.PhysicalBooleanSampler.draw r c htotal T R hStep hTerminal))
        OAI.ContingencyTables.FirstSuccess.uniformLaw) ≤
    ↑(Math115.CompletionRetryBudget.dyadic h)
